<script setup lang="ts">
import {computed,ref,onMounted} from 'vue'
import {useRoute} from 'vue-router'
import {api,errorText} from '../api'
import {json} from '../measurements/model'
import PageHeading from '../components/PageHeading.vue'
import StatePanel from '../components/StatePanel.vue'
import MeasurementsView from './MeasurementsView.vue'
const route=useRoute(),type=computed(()=>String(route.params.type)),names:Record<string,string>={ellipsometry:'椭偏膜厚',rga:'RGA 残余气体',xps:'XPS 光电子能谱',other:'其他仪器'}
const rows=ref<any[]>([]),page=ref(1),total=ref(0),loading=ref(false),error=ref(''),detail=ref<any>(null),detailError=ref(''),busy=ref(false)
async function load(){loading.value=true;error.value='';try{const e=await api<any[]>('/instrument-datasets',{query:{instrument_type:type.value==='ellipsometry'?undefined:type.value,page:page.value,size:20}});rows.value=e.data;total.value=e.meta?.total||0}catch(e){error.value=errorText(e)}finally{loading.value=false}}
async function open(id:number){if(busy.value)return;busy.value=true;detailError.value='';try{detail.value=(await api<any>(`/instrument-datasets/${id}`,{query:{include_channels:true,include_datapoints:true}})).data}catch(e){detailError.value=errorText(e)}finally{busy.value=false}}
onMounted(()=>{if(type.value!=='ellipsometry'&&names[type.value])load()})
</script>
<template><div data-testid="instruments-page"><PageHeading :title="names[type] || '未知仪器入口'" description="统一保留原件与来源，仅展示后端实际存在的结构化数据。"><template #actions><router-link v-if="names[type]" :to="{path:'/imports',query:{instrument:type}}"><el-button type="primary" data-testid="instrument-import">进入统一导入中心</el-button></router-link></template></PageHeading><div class="toolbar"><router-link v-for="(name,key) in names" :key="key" :to="`/instruments/${key}`"><el-button :type="key===type?'primary':'default'">{{ name }}</el-button></router-link><router-link to="/source-files"><el-button>原始文件档案</el-button></router-link></div><section v-if="type==='ellipsometry'" class="panel panel-body"><h2>膜厚正式测量</h2><p>测量点以 nm / mm 等明确单位展示；完整解析精度与原始值保存在测量来源中。</p><router-link to="/measurements"><el-button type="primary" data-testid="ellipsometry-measurements">打开膜厚测量列表</el-button></router-link><p class="field-hint">暂存文件尚未成为正式测量。请先在导入中心逐项核对并确认。</p><MeasurementsView /></section><template v-else-if="names[type]"><el-alert :closable="false" type="info" :title="type==='rga'?'RGA 尚无经过真实文件验证的解析器；上传后可保存原件，待解析。':type==='xps'?'XPS Chart XML 不含可信谱点；VGD 与私有格式本轮仅保留原件，待解析。':'未支持的格式保留原件，不能生成虚构测点。'"/><section class="panel" style="margin-top:20px"><div class="panel-title"><h2>已有仪器数据集</h2><el-button :loading="loading" @click="load">刷新数据集</el-button></div><StatePanel v-if="error" tone="error" title="数据集加载失败" :description="error"><el-button @click="load">重试</el-button></StatePanel><p v-else-if="loading" role="status" class="panel-body">正在读取数据集…</p><StatePanel v-else-if="!rows.length" title="暂无结构化数据集" description="此账户可见范围内未返回数据集。保存原件不会自动创建数据集、通道或谱点。"><router-link :to="{path:'/imports',query:{instrument:type}}"><el-button>上传原件并核对</el-button></router-link></StatePanel><el-table v-else :data="rows"><el-table-column prop="dataset_id" label="数据集 ID"/><el-table-column prop="dataset_code" label="编码"/><el-table-column prop="instrument_type" label="仪器"/><el-table-column prop="sample_mapping_status" label="样品关联状态"/><el-table-column label="详情"><template #default="{row}"><el-button :disabled="busy" @click="open(row.dataset_id)">查看数据集 #{{ row.dataset_id }}</el-button></template></el-table-column></el-table><div class="pagination"><span>共 {{ total }} 项</span><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="prev, pager, next" @current-change="load"/></div></section><StatePanel v-if="detailError" tone="error" title="详情加载失败" :description="detailError"/><section v-if="detail" class="panel panel-body" style="margin-top:20px"><h2>数据集 #{{ detail.dataset_id }}</h2><p>以下为实际来源数据，单位以通道元数据为准。</p><pre>{{ json(detail) }}</pre></section></template><StatePanel v-else title="未识别的仪器类型" description="请选择椭偏膜厚、RGA、XPS 或其他仪器入口。"/></div></template>
<style scoped>h2{font-size:20px}pre{max-height:520px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}</style>
